function kIcon(k){return '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+KI[k]+'</svg>';}
function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var DL=[{day:'Before',text:'You sign, pay, and send the start items.',items:['s0']},{day:'Day 1',text:'Kickoff call, 30-minute, then the tool inventory.',items:['k1','t1']},{day:'Day 2',text:'Two short interviews with front-line staff.',items:['i1']},{day:'Day 3',text:'I map how the work flows today.',items:['m1']},{day:'Day 4',text:'I size the options and pick one to scope.',items:['o1']},{day:'Day 5',text:'Review call: we walk the plan together.',items:['r1']},{day:'After',text:'You decide on Step 2, with no obligation.',items:['a1']}];
function kitDayList(host,rows,title,uid){var s=document.createElement('section');s.className='daylist';s.setAttribute('aria-labelledby',uid);s.innerHTML='<h2 class="daylist-h" id="'+uid+'">'+kEsc(title)+'</h2><ol>'+rows.map(function(r){return '<li'+(r.items?' data-items="'+kEsc(r.items.join(' '))+'"':'')+'><span class="daylist-d">'+kEsc(r.day)+'<span class="daylist-sr">: </span></span><span class="daylist-t">'+kEsc(r.text).replace(/(\d+)-(minute|hour|day)/g,'$1‑$2')+'</span></li>';}).join('')+'</ol>';host.appendChild(s);return s;}
kitDayList(kSlot(),DL,'Your week','dl-stage');
STATES.forEach(function(s,i){kitDayList(kSlot(i),s[0]==='full'?DL:[DL[0],DL[1],DL[6]],'Your week','dl-s'+i);});
